  const goals = [["Chat with CalmBot", 1, 1, 10, MessageCircle], ["Write in your journal", 1, 1, 15, BookOpen], ["Complete mood check", 0, 1, 5, Heart], ["Read something kind", 0, 1, 8, Library]];
